import { button, coins, esc, header } from './views.js';
import { icon } from './icons.js';
import { GOLF_COURSES, golfPar, golfHoleCount, courseRecordKey } from './golf-courses.js';
import { COURSES, getHole, relative } from './courses.js';
import { featuredCourses } from './rotating-courses.js';
export function courseMenu(ui) {
  const golf=ui.mode==='golf',courses=golf?GOLF_COURSES:COURSES;
  const card=(i,feature)=>{
    const c=courses[i],count=golf?golfHoleCount(i):9,unlocked=ui.localPreview||ui.progress.level.level>=c.level;
    const best=ui.progress.data.bests[courseRecordKey(ui.mode,i)],par=Array.from({length:count},(_,j)=>golf?golfPar(i,j):getHole(i,j).par).reduce((a,b)=>a+b,0);
    const reset=feature?.ends?new Date(feature.ends).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'';
    return `<article class="arcade-course ${feature?'featured-course':''}" data-card><img data-course-preview="${ui.mode}:${i}" src="${ui.world.thumbnail(i,ui.mode)}" alt="${esc(c.name)}" loading="lazy" decoding="async"><div class="arcade-course-copy"><div class="course-card-meta">${feature?`<span class="course-slot" title="${!feature.ends?'Always available':feature.label==='Seasonal course'?'Ends':'Changes'} ${esc(reset)}">${esc(feature.label)}</span>`:''}<span>${count} ${count===1?'hole':'holes'} · Par ${par}</span></div><${golf?'h3':'h2'}>${esc(c.name)}</${golf?'h3':'h2'}><p>${esc(c.subtitle)}</p><div class="arcade-course-record"><span>${unlocked?esc(c.difficulty):'Level '+c.level+' · Practice available'}</span><span>Best ${best?relative(best.score):'-'}</span></div>${button(icon('play')+(unlocked?'Play':'Practice'),unlocked?'start':'practice',`data-course="${i}" data-card-primary aria-label="${unlocked?'Play':'Practice'} ${esc(c.name)}"`,'arcade-button arcade-primary')}</div></article>`;
  };
  const miniPage=ui.miniCoursePage===1?1:0,allFeatures=featuredCourses(),longPage=ui.moreCoursePage===1,features=allFeatures.filter(f=>longPage?f.index>=14:f.index<14);
  const section=(id,title,note,cards)=>`<section class="course-section course-section-${id}" aria-labelledby="${id}-courses-heading"><div class="course-section-heading"><h2 id="${id}-courses-heading">${title}</h2>${id==='featured'?`<nav class="more-course-tabs" aria-label="More to play collections">${button('Adventures','more-course-page','data-page="0" aria-pressed="'+!longPage+'"','arcade-button')}${button('Long rounds · 9 holes','more-course-page','data-page="1" aria-pressed="'+longPage+'"','arcade-button')}</nav>`:`<span>${note}</span>`}</div><div class="arcade-courses" style="--course-count:${cards.length}">${cards.join('')}</div></section>`;
  const content=golf?`<div class="course-sections">${section('classic','Classic courses','The original three-hole rounds',[0,1,2].map(i=>card(i)))}${section('featured','More to play','Seasonal · Weekly · Daily · Long rounds',features.map(f=>card(f.index,f)))}</div>`:`<div class="arcade-courses" style="--course-count:${Math.min(3,courses.length-miniPage*3)}">${courses.map((_,i)=>i).slice(miniPage*3,miniPage*3+3).map(i=>card(i)).join('')}</div>`;
  return `${header(ui)}<main class="arcade-page course-menu ${golf?'full-golf-menu':''}"><header class="arcade-page-header">${button('← Back','home','','arcade-button')}<h1>Courses</h1><span>${coins(ui.progress.data.coins)}</span></header><section class="arcade-page-content"><nav class="arcade-switch" aria-label="Golf mode">${[['golf','Full golf'],['mini','Mini-golf']].map(([id,label])=>button(label,'mode',`data-id="${id}" aria-pressed="${ui.mode===id}"`,'arcade-button')).join('')}${golf?`<span class="course-menu-note">${allFeatures.length+3} courses · One clubhouse</span>`:`<span class="course-collection" role="group" aria-label="Mini-golf pages">${[['0','1–3'],['1','4–5']].map(([id,label])=>button(label,'course-collection',`data-id="${id}" aria-pressed="${String(miniPage)===id}"`,'arcade-button')).join('')}</span>`}</nav>${content}<footer class="arcade-course-footer"><div>${button('Community maps','community','','arcade-button')}${button('Map editor · Level 10','editor','','arcade-button')}</div><small>Daily: midnight UTC · Weekly: Monday midnight UTC. Practice and custom maps do not award coins or leaderboard results.</small></footer></section></main>`;
}
